package vn.freshlink.claims;
import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import vn.freshlink.common.api.ApiResponse;import vn.freshlink.identity.Actor;
@RestController @RequestMapping("/api/claims") public class ClaimWorkflowController{
 private final JdbcTemplate jdbc;public ClaimWorkflowController(JdbcTemplate j){jdbc=j;}
 public record Transition(@NotBlank @Pattern(regexp="VERIFYING|WAITING_PARTNER|REJECTED|CLOSED") String status,Long assigneeId,@NotBlank @Size(max=1000) String note){}
 @PatchMapping("/{id}/status") @Transactional public ApiResponse<?> transition(@AuthenticationPrincipal Actor a,@PathVariable long id,@jakarta.validation.Valid @RequestBody Transition r){a.requireRole("CUSTOMER_SUPPORT");var rows=jdbc.queryForList("SELECT * FROM complaints WHERE complaint_id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy khiếu nại");String old=rows.get(0).get("status").toString();Map<String,Set<String>> allowed=Map.of("NEW",Set.of("VERIFYING","REJECTED"),"VERIFYING",Set.of("WAITING_PARTNER","REJECTED","CLOSED"),"WAITING_PARTNER",Set.of("VERIFYING","REJECTED","CLOSED"),"RESOLVED",Set.of("CLOSED"));if(!allowed.getOrDefault(old,Set.of()).contains(r.status()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Chuyển trạng thái khiếu nại không hợp lệ");Long assignee=r.assigneeId()==null?a.userId():r.assigneeId();if(jdbc.queryForObject("SELECT COUNT(*) FROM users u JOIN organization_members m ON m.user_id=u.user_id JOIN member_roles mr ON mr.member_id=m.member_id JOIN roles ro ON ro.role_id=mr.role_id WHERE u.user_id=? AND u.status='ACTIVE' AND ro.role_code='CUSTOMER_SUPPORT'",Integer.class,assignee)==0)throw new IllegalArgumentException("Người phụ trách không hợp lệ");jdbc.update("UPDATE complaints SET status=?,assigned_to=?,final_resolution=IF(? IN ('REJECTED','CLOSED'),?,final_resolution),resolved_at=IF(?='REJECTED',UTC_TIMESTAMP(3),resolved_at),closed_at=IF(?='CLOSED',UTC_TIMESTAMP(3),closed_at) WHERE complaint_id=?",r.status(),assignee,r.status(),r.note(),r.status(),r.status(),id);jdbc.update("INSERT INTO audit_logs(actor_user_id,action_code,entity_type,entity_id,old_data,new_data) VALUES (?,'TRANSITION_CLAIM','COMPLAINT',?,JSON_OBJECT('status',?),JSON_OBJECT('status',?,'assigneeId',?,'note',?))",a.userId(),id,old,r.status(),assignee,r.note());return ApiResponse.success(id,"Đã cập nhật khiếu nại");}
}
